<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserGrantedClientScopes\Domain\ValueObject\Holder\UserGrantedClientScopesScopeAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserGrantedClientScopesScopeAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserGrantedClientScopesScopeAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getScope returns null on a freshly created holder.
     */
    public function testScopeNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserGrantedClientScopesScopeAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isScopeAssigned());
        $this->assertNull($holder->getScope());
    }
}
class ImplWithUserGrantedClientScopesScopeAttributeHolderUnitTest
{
    use UserGrantedClientScopesScopeAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedScopeRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultScope();
    }
}
